def key(ch):
    code='Digit'+ch
    cdp('Input.dispatchKeyEvent', type='rawKeyDown', key=ch, code=code)
    cdp('Input.dispatchKeyEvent', type='char', text=ch)
    cdp('Input.dispatchKeyEvent', type='keyUp', key=ch, code=code)
for ch in "12": key(ch)
for ch in "2026": key(ch)
